INSERT INTO `npc_text` (`ID`,`text0_0`,`text1_0`,`text2_0`,`text3_0`,`text4_0`,`text5_0`,`text6_0`,`text7_0`,`VerifiedBuild`) VALUES
(@STORIES_START+0,'Back when I was young, I got lost in Duskwood for three days.','Every night the worgen howled closer to my little fire.','On the third night, a figure in a black cloak sat down across from me.','It just said: "Follow the crows to Darkshire." Then it was gone.','I followed the crows. To this day I don\'t know who that was.',NULL,NULL,NULL,'-1'),
(@STORIES_START+1,'Duskwood gives me the creeps.','Worgen? I\'d have run all the way home.','Maybe a ghost of the Night Watch?','Brrr...',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+2,'Did I ever tell you about the murloc that stole my boots?','I was fishing near Westfall, boots next to me in the sand.','One gurgle, one splash, and my boots were marching into the sea.','A week later I saw a murloc chieftain wearing them. Both on one foot.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+3,'Mrglglgl!','Did you get them back?','Both on one foot? Hah!','Murlocs are the worst.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+4,'My grandfather fought at the Dark Portal in the Second War.','He said the sky there was red as blood, day and night.','When the portal was destroyed, the ground shook for an hour.','He kept a shard of that stone until the day he died.','I carry it with me now. For luck, I suppose.',NULL,NULL,NULL,'-1'),
(@STORIES_START+5,'A true hero.','Can I see the shard?','The Blasted Lands still look like that.','May he rest in peace.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+6,'Once I tried to tame a raptor in the Barrens.','I had meat, rope and a lot of confidence.','The raptor had teeth and six friends.','I spent the night on top of a kodo skeleton, singing to keep them away.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+7,'Six friends! Hahaha!','Did the singing work?','Raptors are no pets.','I\'d pay to hear that song.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+8,'In Stranglethorn I met a goblin who sold maps to hidden treasure.','Ten gold for one map. I bought three.','All three X\'s pointed to his own shop.','He had a big sign: "Treasure inside! Everything must go!"',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+9,'Typical goblin.','Thirty gold... ouch.','Hah! Clever little fellow.','Did you buy anything in the shop?',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+10,'I once guarded a caravan through the Badlands.','The heat was so bad our water turned warm as soup.','At night, we heard the black dragons roar from Lethlor Ravine.','A whelp landed on our wagon, ate our cheese and flew off.','We reported one missing cheese wheel, cause: dragon attack.',NULL,NULL,NULL,'-1'),
(@STORIES_START+11,'A cheese thief with wings!','The Badlands are no place for caravans.','At least it wasn\'t the adult one.','Hahaha, dragon attack!',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+12,'Have you ever seen the northern lights over Northrend?','I camped on a glacier in the Borean Tundra once.','The sky turned green and blue, like the whole world was breathing.','For a moment I forgot the Scourge, the cold, everything.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+13,'That sounds beautiful.','I\'d freeze to death up there.','Someday I\'ll see that.','Beauty and danger, side by side.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+14,'My first dungeon was the Deadmines.','Our tank ran in before anyone was ready.','Our healer ran out the other way.','Somehow we still defeated VanCleef. I have no idea how.','I still hear that cannon go off in my dreams.',NULL,NULL,NULL,'-1'),
(@STORIES_START+15,'Classic tank.','Hahaha, the healer!','The cannon! I remember that!','Luck of the brave.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+16,'There\'s an old troll tale about the loa of the moon.','They say he only speaks to those who can\'t sleep.','He tells you one secret, and you must never repeat it.','I haven\'t slept well for years. Draw your own conclusions.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+17,'So what was the secret?','Oh, come on, tell us!','I\'d rather sleep well.','Mysterious...',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+18,'Once I got into a drinking contest in Ironforge.','Against a dwarf. I know, I know.','After the ninth mug I saw two Great Forges.','I woke up in the Deeprun Tram, halfway to Stormwind.','The dwarf? He was still drinking when I came back.',NULL,NULL,NULL,'-1'),
(@STORIES_START+19,'Never challenge a dwarf.','Nine mugs? Respect.','The tram! Hahaha!','Dwarves are made of stone, I swear.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+20,'Near Tarren Mill I met a farmer who talked to his scarecrow.','He said it warned him every time the Forsaken came close.','I laughed. Then the scarecrow turned its head toward me.','I left before dinner. Very politely. Very fast.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+21,'Nope. Nope nope nope.','It turned its head?!','Hillsbrad is full of strange folk.','Smart move.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+22,'I learned to fish from an old night elf in Auberdine.','He said: "The fish know when you\'re impatient."','I sat there for six hours without a single bite.','He caught forty. He was humming the whole time.','Now I hum too. I still catch nothing, but I\'m happier.',NULL,NULL,NULL,'-1'),
(@STORIES_START+23,'Patience is a skill.','Forty? That\'s unfair.','Happiness is worth more than fish.','Hum us the tune!',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+24,'In the Scarlet Monastery I saw a man pray for two days straight.','No food, no water, just prayer.','I asked him what he was praying for.','He said: "That I\'m wrong about everything."','I think about him a lot.',NULL,NULL,NULL,'-1'),
(@STORIES_START+25,'That\'s... sad.','The Crusade broke many good men.','Deep words.','Maybe he found his answer.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+26,'I once rode a gryphon that hated me.','Every flight, it did a loop over Loch Modan.','The flight master swore it never did that with anyone else.','I brought it an apple once. It ate the apple and the bag.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+27,'Gryphons have opinions.','A loop! I\'d lose my lunch.','And the bag! Hahaha!','Maybe it liked you, in its own way.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+28,'There is a spring in Ashenvale that shows your future.','I looked into it, of course.','I saw myself, older, sitting at a campfire like this one.','Telling a story about a spring in Ashenvale.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+29,'Wait... that\'s now?','That gives me chills.','Do you look older now?','The spirits have humor.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+30,'A gnome in Booty Bay sold me a "self-cooking pot".','You put in water, press the button, and it cooks.','It cooked, all right. It cooked itself, the table and half the tavern.','The gnome called it a "successful field test".',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+31,'Gnomish engineering...','Half the tavern?!','Successful, for the fire maybe.','Hahaha, of course it exploded.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+32,'When I was a recruit, the sergeant made us run around Goldshire.','Twenty laps, full armor, every morning.','One morning a kobold joined us and ran along.','He finished before half of us. The sergeant wanted to recruit him.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+33,'You no take candle!','A kobold recruit! Hahaha!','Twenty laps in plate? Ouch.','Did he join the army?',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+34,'Ever heard of the ghost ship off the coast of Darkshore?','Sailors say it appears when the fog is thickest.','No lights, no crew, but you hear someone ringing a bell.','I heard that bell once. Next morning, my boat was full of seaweed.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+35,'That\'s how legends start.','I\'m never sailing at night again.','Maybe just a lost fisherman?','Creepy...',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+36,'I once helped a tauren look for his lost kodo.','We searched Mulgore for two whole days.','Finally found it in Thunder Bluff, on top of the elevator.','To this day, nobody knows how it got up there.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+37,'On the elevator?!','Kodos are smarter than they look.','Hah! Earth Mother works in strange ways.','I love this story.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+38,'The worst night of my life was in Karazhan.','The ghosts there throw a dinner party every night.','They invited me. I was polite. I sat down.','The soup was cold, the host was dead, and the music never stopped.','I left at sunrise. They asked me to come back next week.',NULL,NULL,NULL,'-1'),
(@STORIES_START+39,'Did you go back?','Medivh\'s tower is cursed.','Cold soup is the real horror.','I\'d have run screaming.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+40,'In Nagrand I watched the floating islands at dawn.','Waterfalls poured off them into nothing.','An old orc sat next to me and said nothing for an hour.','Then he said: "This was home, before we forgot ourselves."',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+41,'Nagrand is the last beautiful place in Outland.','That old orc knew grief.','Heavy words.','I\'d like to see those islands.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+42,'I once bet my whole purse on a race in Gadgetzan.','Two goblins, two rocket cars, one straight track.','Both rockets exploded at the start.','The bookie said nobody won, so he kept all the money.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+43,'Goblins always win.','Of course they exploded.','You never learn, do you?','That bookie was the real racer.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+44,'My mentor was a priest who never raised her voice.','Once, bandits surrounded our camp.','She walked out, looked at their leader, and offered him tea.','He drank it. They left. Nobody ever understood why.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+45,'What was in that tea?','The Light works in quiet ways.','I want to meet her.','Kindness is stronger than steel.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+46,'I got chased by a yeti in Alterac once.','I ran, it ran. I slid down a hill, it slid down a hill.','At the bottom it stopped, looked at me, and laughed.','I swear, the yeti was just playing.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+47,'A playful yeti! Hahaha!','I don\'t believe a word of it.','Did you play again?','Yetis laughing... what next?',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+48,'They say Dalaran was once lifted into the sky in one night.','A farmer near the old crater told me he watched it.','"First the city glowed, then it hummed, then it simply left."','He\'s been waiting for it to come back ever since. Owes them money.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+49,'A flying city. Only mages.','He owes them money? Hahaha!','I\'d love to see it hum.','Mages never do anything quietly.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+50,'I spent a winter with the Wintersaber Trainers in Winterspring.','Every morning, I fed the cubs frozen fish.','One of them followed me everywhere, even to the privy.','When I left, it sat by the gate and waited for days.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+51,'That\'s so sweet.','Even to the privy! Hahaha!','You should go back for it.','Poor little thing.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+52,'Ever stood inside the Crossroads during a centaur raid?','Arrows everywhere, the whole palisade shaking.','And the innkeeper just kept pouring drinks.','He said: "Raids come and go. Thirst is forever."',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+53,'A wise innkeeper.','Centaurs are nasty.','I\'ll drink to that!','Hah! Thirst is forever.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+54,'In Zul\'Drak I found a troll statue that cried.','Real tears, running down the stone.','I wiped its face with my sleeve.','The next day, the tears were gone and a flower grew at its feet.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+55,'That\'s beautiful.','The Drakkari gods are dying. Maybe it was grief.','A small kindness.','I\'ve got goosebumps.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+56,'I once tried to sneak into the Undercity as a joke.','I painted my face grey and walked like my back hurt.','A Forsaken guard stopped me and asked if I needed a healer.','I said yes. He sent me to the apothecary. Worst checkup of my life.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+57,'You what?!','The apothecary! Hahaha!','You\'re lucky to be alive.','That\'s the dumbest brave thing I ever heard.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+58,'A dwarf in the Wetlands taught me how to read the rain.','Soft rain means crocolisks sleep. Hard rain means they\'re hungry.','I asked what no rain means.','He said: "In the Wetlands? That\'s never happened."',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+59,'True, it always rains there.','Hah! Never happened!','Useful knowledge, actually.','My boots are still wet from the Wetlands.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+60,'Have you heard about the headless horseman of Sorrow Hill?','Once a year he rides and looks for his head.','A child once offered him a pumpkin instead.','He took it. And now every autumn, pumpkins burn in Goldshire.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+61,'Hallow\'s End! I love it.','A pumpkin head, hahaha.','Don\'t say his name too loud.','Brave child.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+62,'I got my first sword from a blacksmith in Lakeshire.','It was too heavy, too long, and slightly bent.','He said: "It\'s not the sword, it\'s who holds it."','I found out later he just wanted to get rid of it.','But the words stuck. And so did the bend.',NULL,NULL,NULL,'-1'),
(@STORIES_START+63,'Smart smith.','Still carrying it?','Hah! The bend stayed!','Good words, even if it was a trick.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+64,'Shattrath at night is something else.','The naaru hum, and the whole city glows softly.','I sat on the Terrace of Light and just listened.','A draenei child sat next to me and said: "They sing for us."',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+65,'That\'s lovely.','I\'ve never heard a naaru sing.','Children know these things.','Peace in the middle of chaos.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+66,'I once guarded Nethergarde Keep for a month.','Every night, something moved out in the Blasted Lands.','On the last night it came close. Big, red eyes.','It was a lost boar. Scared us half to death, that pig.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+67,'A boar! Hahaha!','Better a boar than a demon.','I\'d have shot first.','Nethergarde makes everyone nervous.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+68,'My mother always said: never trust a sleeping dragon.','I thought that was a figure of speech.','Then I found one sleeping in the Swamp of Sorrows.','I tiptoed past. It opened one eye and said: "Good choice."',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+69,'It talked?!','Listen to your mother.','A green dragon, maybe. They dream.','I\'d have fainted.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+70,'Wintergrasp. Ever fought there?','Siege engines, fire, snow, all at once.','I drove a demolisher straight into a wall. Wrong wall.','Our own. The commander made me rebuild it with my hands.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+71,'Our own wall! Hahaha!','That\'s a story for the guild.','Easy mistake in the snow.','Did the commander ever forgive you?',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+72,'There\'s a little girl in Southshore who draws every traveler.','She drew me with a crown and a dragon.','I told her I\'m just a simple adventurer.','She said: "Not yet." I still have that drawing.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+73,'A seer in the making.','A crown! Your Majesty!','Keep that drawing safe.','"Not yet." I like that.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+74,'I once got stuck in a gnomish teleporter.','I was in Gadgetzan and Everlook at the same time for a second.','Half of me was hot, the other half freezing.','When I came out, my hair was a different color.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+75,'That explains a lot.','Gnomes should not build teleporters.','What color was it before?','Hahaha, both at once!',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+76,'In Feralas I climbed one of the giant trees.','It took me a whole day to reach the top.','Up there, I found a nest with a sleeping hippogryph.','I climbed down very, very quietly. That took two days.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+77,'Two days down! Hahaha!','Brave, or foolish.','Feralas trees are enormous.','I\'d have woken it by accident.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+78,'Once I found a note in a bottle on the beach of Tanaris.','It said: "If you find this, I\'m on the island to the east."','I rowed out there. The island was empty except for a hut.','Inside was another bottle: "Too late, I found a boat. Thanks anyway!"',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+79,'Hahaha, thanks anyway!','At least he was polite.','All that rowing for nothing.','I love a happy ending.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+80,'The Plaguelands used to be the best farmland in Lordaeron.','My uncle grew wheat near Andorhal.','He left the day the grain turned black.','He still bakes bread every morning. He says it\'s his way of remembering.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+81,'So much was lost.','Your uncle is a strong man.','The Scourge will pay for that.','I\'d like to taste that bread.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+82,'I trained with a monk who could balance on one finger.','For a year I tried to copy him.','I broke three fingers and a table.','He said: "Good. Now you know where your limits are."',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+83,'A table too? Hahaha!','Hard teacher.','Wise words, painful lesson.','Show us the finger trick!',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+84,'There is a hidden cave behind a waterfall in Un\'Goro.','Inside, the walls glow with crystals of every color.','I sat there for hours. Then a devilsaur walked past outside.','I sat there for many more hours after that.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+85,'Devilsaur! I\'d hide too.','Where exactly is that cave?','Hahaha, many more hours.','Un\'Goro is full of wonders.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+86,'I\'ll never forget the first time I saw Stormwind.','The gates, the statues, the canals, all white in the sun.','I stood on the bridge so long, a guard asked if I was lost.','I said no. I was finally home.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+87,'Stormwind is a sight.','I know that feeling.','Home is where your heart is.','That\'s a good ending.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+88,'A shaman in Orgrimmar once read my future from bones.','He frowned, shook them again, frowned harder.','I asked: "Is it bad?" He said: "No, these are chicken bones."','"They only know about lunch."',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+89,'Chicken bones! Hahaha!','So what about lunch?','The spirits have humor.','Classic Orgrimmar.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+90,'I was on the boat to Northrend when the storm hit.','Waves higher than the mast, everybody praying.','The captain just stood there, smoking his pipe.','Afterwards I asked why he wasn\'t afraid. He said: "I was. I just hid it better."',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+91,'That\'s what courage is.','I hate boats.','A good captain.','I\'ll remember that.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+92,'My brother tried to learn fire magic by himself.','First try: he set his eyebrows on fire.','Second try: the curtains.','Third try, he finally made a fireball. Right into our mother\'s soup.','He\'s an archmage now. He still doesn\'t have eyebrows.',NULL,NULL,NULL,'-1'),
(@STORIES_START+93,'No eyebrows! Hahaha!','Your poor mother.','Every mage starts somewhere.','Did the soup survive?',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+94,'I once stayed a night at the Shrine of the Fallen Warrior.','Nobody else was there, just me and the wind.','At midnight I heard footsteps walk around the shrine, slowly.','In the morning, someone had left fresh flowers.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+95,'A spirit keeping watch.','That\'s respectful, not scary.','The Barrens hold many memories.','I have chills.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+96,'I saved a gnome from a pack of wolves in Dun Morogh.','To thank me, he gave me a mechanical squirrel.','It followed me for a year and talked in my sleep.','One day it ran off with a real squirrel. I hope they\'re happy.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+97,'True love! Hahaha!','It talked in your sleep?','Gnomes make the strangest gifts.','I hope they\'re happy too.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+98,'Let me tell you about the best meal I ever had.','It wasn\'t in a city or a tavern. It was right here.','A fire, some stale bread, and friends who listened to bad stories.','So thank you. Now someone else tell one, my throat is dry.',NULL,NULL,NULL,NULL,'-1'),
(@STORIES_START+99,'To friends!','Your stories aren\'t bad.','Pass the bread.','Aww.',NULL,NULL,NULL,NULL,'-1');
